#include <iostream>
#include <string>

class Course {
private:
    std::string courseName;
    std::string* students;
    int numberOfStudents;
    int capacity;

public:
    Course(const std::string& name, int cap) 
        : courseName(name), numberOfStudents(0), capacity(cap), students(new std::string[cap]) {}

    ~Course() {
        delete[] students;
    }

    // Copy constructor (Deep copy)
    Course(const Course& other)
        : courseName(other.courseName),
          numberOfStudents(other.numberOfStudents),
          capacity(other.capacity),
          students(new std::string[other.capacity]) {
        for (int i = 0; i < numberOfStudents; ++i) {
            students[i] = other.students[i];
        }
    }

    // Overloaded assignment operator (Deep copy)
    Course& operator=(const Course& other) {
        if (this != &other) { // Guard against self-assignment
            delete[] students;
            courseName = other.courseName;
            numberOfStudents = other.numberOfStudents;
            capacity = other.capacity;
            students = new std::string[capacity];
            for (int i = 0; i < numberOfStudents; ++i) {
                students[i] = other.students[i];
            }
        }
        return *this;
    }

    void addStudent(const std::string& studentName) {
        if (numberOfStudents < capacity) {
            students[numberOfStudents++] = studentName;
        }
    }

    std::string getStudent(int index) const {
        if (index >= 0 && index < numberOfStudents) {
            return students[index];
        }
        return "";
    }
};

int main() {
    Course course1("Java Programming", 10);
    Course course2("C++ Programming", 14);

    // Perform deep assignment
    course2 = course1;

    course1.addStudent("Peter Pan");
    course2.addStudent("Lisa Ma");

    std::cout << "students in course1: " << course1.getStudent(0) << "\n";
    std::cout << "students in course2: " << course2.getStudent(0) << "\n";

    return 0;
}

#include <iostream>
#include <algorithm>

class DynamicBuffer {
private:
    int* data;
    size_t size;

public:
    // Standard Constructor
    DynamicBuffer(size_t n, int initVal = 0) : size(n), data(new int[n]) {
        std::fill(data, data + size, initVal);
    }

    // 1. Destructor
    ~DynamicBuffer() {
        delete[] data;
    }

    // 2. Copy Constructor
    DynamicBuffer(const DynamicBuffer& other) : size(other.size), data(new int[other.size]) {
        std::copy(other.data, other.data + size, data);
    }

    // 3. Copy Assignment Operator (handling self-assignment)
    DynamicBuffer& operator=(const DynamicBuffer& other) {
        if (this != &other) {
            delete[] data; // Clean up old resource
            size = other.size;
            data = new int[size];
            std::copy(other.data, other.data + size, data);
        }
        return *this;
    }

    void set(size_t index, int val) {
        if (index < size) data[index] = val;
    }

    int get(size_t index) const {
        return (index < size) ? data[index] : 0;
    }
};

int main() {
    DynamicBuffer buf1(2, 100);
    DynamicBuffer buf2(2, 200);

    // Chain assignment
    buf2 = buf1;
    buf1.set(0, 999);

    std::cout << "buf1[0]: " << buf1.get(0) << "\n";
    std::cout << "buf2[0]: " << buf2.get(0) << "\n";

    // Test self-assignment safety
    buf2 = buf2;
    std::cout << "After self-assignment buf2[0]: " << buf2.get(0) << "\n";

    return 0;
}
